import os,subprocess,sys
from pathlib import Path
def import_text(source,target,preferred):
    available=subprocess.check_output(['locale','-a'],text=True).splitlines()
    candidates=([preferred] if isinstance(preferred,str) and preferred in available else [])+sorted(available)
    chosen=None
    for candidate in dict.fromkeys(candidates):
        env={**os.environ,'LC_ALL':candidate,'LANG':candidate,'PYTHONUTF8':'0','PYTHONCOERCECLOCALE':'0'}
        probe=subprocess.run(['locale','charmap'],env=env,capture_output=True,text=True)
        if probe.returncode==0 and probe.stdout.strip().replace('-','').upper()=='UTF8':chosen=candidate;break
    if chosen is None:raise RuntimeError('no installed UTF8 locale')
    env={**os.environ,'LC_ALL':chosen,'LANG':chosen,'PYTHONUTF8':'0','PYTHONCOERCECLOCALE':'0'}
    code="import json,locale,sys; text=open(sys.argv[1],'r').read(); f=open(sys.argv[2],'x',encoding='utf-8'); json.dump({'text':text,'encoding':locale.getencoding()},f,ensure_ascii=False); f.close()"
    result=subprocess.run([sys.executable,'-X','utf8=0','-c',code,str(source),str(target)],env=env,capture_output=True,text=True)
    if result.returncode:raise RuntimeError(result.stderr)
    return chosen
```

原题说明：
确认进程实际环境及 setlocale 失败信息，缺失 locale 可能令程序退回 C 语义或直接拒绝启动。安装发行版对应语言数据或生成所需 locale，使用真实存在且符合输入编码的名称；受控重启读取环境的进程。验证中文、ASCII和非法字节输入，不能只把变量写成 UTF-8 就视为支持。

